<?php
require __DIR__ . '/app/bootstrap.php';
$page = $_GET['page'] ?? (current_user() ? 'dashboard' : 'login');
$statuses = ['diajukan','review','proposal','penelitian','sidang','selesai','revisi'];

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    verify_csrf();
    $action = $_POST['action'] ?? '';
    try {
        if ($action === 'login') {
            $stmt = db()->prepare('SELECT * FROM users WHERE email=?'); $stmt->execute([strtolower(trim($_POST['email'] ?? ''))]); $user = $stmt->fetch();
            if (!$user || !password_verify($_POST['password'] ?? '', $user['password'])) throw new RuntimeException('Email atau kata sandi tidak sesuai.');
            session_regenerate_id(true); unset($user['password']); $_SESSION['user'] = $user; redirect('index.php');
        }
        require_login();
        if ($action === 'logout') { $_SESSION = []; session_destroy(); redirect('index.php?page=login'); }
        if ($action === 'user_save') {
            require_role(['admin']); $id=(int)($_POST['id']??0); $name=trim($_POST['name']??''); $email=strtolower(trim($_POST['email']??'')); $role=$_POST['role']??'';
            if ($name==='' || !filter_var($email,FILTER_VALIDATE_EMAIL) || !in_array($role,['admin','dosen','mahasiswa'],true)) throw new RuntimeException('Data pengguna belum valid.');
            $number=trim($_POST['student_number']??'') ?: null; $dept=trim($_POST['department']??'') ?: null; $password=$_POST['password']??'';
            if ($id) { if ($password!=='') { if (strlen($password)<10) throw new RuntimeException('Kata sandi minimal 10 karakter.'); db()->prepare('UPDATE users SET name=?,email=?,role=?,student_number=?,department=?,password=? WHERE id=?')->execute([$name,$email,$role,$number,$dept,password_hash($password,PASSWORD_DEFAULT),$id]); } else db()->prepare('UPDATE users SET name=?,email=?,role=?,student_number=?,department=? WHERE id=?')->execute([$name,$email,$role,$number,$dept,$id]); }
            else { if (strlen($password)<10) throw new RuntimeException('Kata sandi minimal 10 karakter.'); db()->prepare('INSERT INTO users(name,email,password,role,student_number,department) VALUES(?,?,?,?,?,?)')->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role,$number,$dept]); }
            flash('success','Data pengguna berhasil disimpan.'); redirect('index.php?page=users');
        }
        if ($action === 'user_delete') { require_role(['admin']); $id=(int)$_POST['id']; if ($id===(int)current_user()['id']) throw new RuntimeException('Akun yang sedang digunakan tidak dapat dihapus.'); db()->prepare('DELETE FROM users WHERE id=?')->execute([$id]); flash('success','Pengguna dihapus.'); redirect('index.php?page=users'); }
        if ($action === 'submission_save') {
            $id=(int)($_POST['id']??0); $title=trim($_POST['title']??''); $description=trim($_POST['description']??'');
            if ($title==='') throw new RuntimeException('Judul tugas akhir wajib diisi.');
            if ($id && !can_access_submission($id)) throw new RuntimeException('Anda tidak dapat mengakses pengajuan ini.');
            if (is_role('mahasiswa')) {
                if ($id) db()->prepare('UPDATE submissions SET title=?,description=? WHERE id=? AND student_id=?')->execute([$title,$description,$id,current_user()['id']]);
                else db()->prepare('INSERT INTO submissions(title,description,student_id) VALUES(?,?,?)')->execute([$title,$description,current_user()['id']]);
            } else {
                $student=(int)($_POST['student_id']??0); $lecturer=(int)($_POST['lecturer_id']??0) ?: null; $status=$_POST['status']??'diajukan';
                if (!in_array($status,$statuses,true)) throw new RuntimeException('Status tidak valid.');
                if ($id) db()->prepare('UPDATE submissions SET title=?,description=?,student_id=?,lecturer_id=?,status=? WHERE id=?')->execute([$title,$description,$student,$lecturer,$status,$id]);
                else db()->prepare('INSERT INTO submissions(title,description,student_id,lecturer_id,status) VALUES(?,?,?,?,?)')->execute([$title,$description,$student,$lecturer,$status]);
            }
            flash('success','Pengajuan berhasil disimpan.'); redirect('index.php?page=submissions');
        }
        if ($action === 'submission_delete') { require_role(['admin']); db()->prepare('DELETE FROM submissions WHERE id=?')->execute([(int)$_POST['id']]); flash('success','Pengajuan dan data terkait dihapus.'); redirect('index.php?page=submissions'); }
        if ($action === 'guidance_save') {
            $submission=(int)($_POST['submission_id']??0); if (!can_access_submission($submission)) throw new RuntimeException('Anda tidak dapat mengakses pengajuan ini.');
            $note=trim($_POST['note']??''); $date=$_POST['meeting_date']??''; if ($note==='' || !$date) throw new RuntimeException('Tanggal dan catatan bimbingan wajib diisi.');
            db()->prepare('INSERT INTO guidances(submission_id,author_id,meeting_date,note) VALUES(?,?,?,?)')->execute([$submission,current_user()['id'],$date,$note]); flash('success','Catatan bimbingan ditambahkan.'); redirect('index.php?page=detail&id='.$submission);
        }
        if ($action === 'guidance_delete') { $id=(int)$_POST['id']; $q=db()->prepare('SELECT * FROM guidances WHERE id=?'); $q->execute([$id]); $g=$q->fetch(); if (!$g || !can_access_submission((int)$g['submission_id']) || (!in_array(current_user()['role'],['admin','dosen'],true) && (int)$g['author_id']!==(int)current_user()['id'])) throw new RuntimeException('Tidak diizinkan menghapus catatan ini.'); db()->prepare('DELETE FROM guidances WHERE id=?')->execute([$id]); flash('success','Catatan bimbingan dihapus.'); redirect('index.php?page=detail&id='.$g['submission_id']); }
        if ($action === 'document_upload') {
            $submission=(int)($_POST['submission_id']??0); if (!can_access_submission($submission)) throw new RuntimeException('Anda tidak dapat mengakses pengajuan ini.');
            $file=$_FILES['document']??null; if (!$file || $file['error']!==UPLOAD_ERR_OK) throw new RuntimeException('Pilih dokumen yang berhasil diunggah.');
            if ($file['size']>$config['max_upload_bytes']) throw new RuntimeException('Ukuran maksimal dokumen adalah 10 MB.');
            $ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION)); $allowed=['pdf','doc','docx','jpg','jpeg','png']; if (!in_array($ext,$allowed,true)) throw new RuntimeException('Format yang diizinkan: PDF, DOC, DOCX, JPG, PNG.');
            if (!is_dir($config['upload_dir']) && !mkdir($config['upload_dir'],0750,true)) throw new RuntimeException('Folder penyimpanan tidak dapat dibuat.');
            $stored=bin2hex(random_bytes(20)).'.'.$ext; if (!move_uploaded_file($file['tmp_name'],$config['upload_dir'].'/'.$stored)) throw new RuntimeException('Gagal menyimpan dokumen.');
            $mime=(new finfo(FILEINFO_MIME_TYPE))->file($config['upload_dir'].'/'.$stored) ?: 'application/octet-stream';
            db()->prepare('INSERT INTO documents(submission_id,uploader_id,original_name,stored_name,mime_type,file_size) VALUES(?,?,?,?,?,?)')->execute([$submission,current_user()['id'],basename($file['name']),$stored,$mime,$file['size']]); flash('success','Dokumen berhasil diunggah.'); redirect('index.php?page=detail&id='.$submission);
        }
        if ($action === 'document_delete') { $id=(int)$_POST['id']; $q=db()->prepare('SELECT * FROM documents WHERE id=?');$q->execute([$id]);$doc=$q->fetch();if(!$doc||!can_access_submission((int)$doc['submission_id'])||(!in_array(current_user()['role'],['admin','dosen'],true)&&(int)$doc['uploader_id']!==(int)current_user()['id']))throw new RuntimeException('Tidak diizinkan menghapus dokumen ini.'); @unlink($config['upload_dir'].'/'.$doc['stored_name']);db()->prepare('DELETE FROM documents WHERE id=?')->execute([$id]);flash('success','Dokumen dihapus.');redirect('index.php?page=detail&id='.$doc['submission_id']); }
        throw new RuntimeException('Aksi tidak dikenali.');
    } catch (Throwable $ex) { flash('danger', $ex instanceof PDOException && $ex->getCode()==='23000' ? 'Email tersebut sudah digunakan.' : $ex->getMessage()); redirect($_SERVER['HTTP_REFERER'] ?? 'index.php'); }
}

if ($page==='download') {
    require_login(); $q=db()->prepare('SELECT * FROM documents WHERE id=?');$q->execute([(int)($_GET['id']??0)]);$doc=$q->fetch();
    if (!$doc || !can_access_submission((int)$doc['submission_id'])) { http_response_code(404); exit('Dokumen tidak ditemukan.'); }
    $path=$config['upload_dir'].'/'.$doc['stored_name']; if (!is_file($path)) { http_response_code(404); exit('Berkas tidak tersedia.'); }
    header('Content-Type: '.$doc['mime_type']); header('Content-Length: '.filesize($path)); header('Content-Disposition: attachment; filename="'.rawurlencode($doc['original_name']).'"'); readfile($path); exit;
}
if ($page!=='login') require_login();
