    ?><div class="welcome"><div><p class="eyebrow">RUANG KERJA AKADEMIK</p><h2>Halo, <?=e(explode(' ',current_user()['name'])[0])?> 👋</h2><p>Pantau progres dan kelola tugas akhir Anda dengan lebih teratur.</p></div><a class="button light" href="index.php?page=submission_form">＋ Pengajuan baru</a></div><div class="stats-grid"><article class="stat-card"><span class="stat-icon indigo">▤</span><div><span>Total pengajuan</span><strong><?=$total?></strong></div><small>Semua tugas akhir</small></article><article class="stat-card"><span class="stat-icon green">✓</span><div><span>Selesai</span><strong><?=$done?></strong></div><small>Pengajuan tuntas</small></article><article class="stat-card"><span class="stat-icon amber">◷</span><div><span>Dalam proses</span><strong><?=$total-$done?></strong></div><small>Masih berjalan</small></article></div><div class="section-heading"><div><p class="eyebrow">AKTIVITAS TERBARU</p><h2>Pengajuan tugas akhir</h2></div><a class="text-link" href="index.php?page=submissions">Lihat semua →</a></div><div class="panel table-wrap"><table><thead><tr><th>Judul</th><?php if(!is_role('mahasiswa')):?><th>Mahasiswa</th><?php endif;?><th>Pembimbing</th><th>Status</th><th>Terakhir diperbarui</th><th></th></tr></thead><tbody><?php foreach($recent as $r):?><tr><td><a class="table-title" href="index.php?page=detail&id=<?=$r['id']?>"><?=e($r['title'])?></a><small class="table-sub">#TA-<?=str_pad((string)$r['id'],4,'0',STR_PAD_LEFT)?></small></td><?php if(!is_role('mahasiswa')):?><td><?=e($r['student_name'])?></td><?php endif;?><td><?=e($r['lecturer_name']??'Belum ditentukan')?></td><td><?=status_badge($r['status'])?></td><td><?=e(date('d M Y',strtotime($r['updated_at'])))?></td><td><a class="icon-link" href="index.php?page=detail&id=<?=$r['id']?>">→</a></td></tr><?php endforeach;?><?php if(!$recent):?><tr><td colspan="6" class="empty">Belum ada pengajuan. Mulai dengan membuat pengajuan pertama.</td></tr><?php endif;?></tbody></table></div><?php page_end(); exit;
