if ($page==='detail') { $id=(int)($_GET['id']??0);$q=db()->prepare('SELECT s.*,u.name student_name,u.email student_email,u.student_number,l.name lecturer_name FROM submissions s JOIN users u ON u.id=s.student_id LEFT JOIN users l ON l.id=s.lecturer_id WHERE s.id=?');$q->execute([$id]);$s=$q->fetch();if(!$s||!can_access_submission($id)){http_response_code(404);exit('Pengajuan tidak ditemukan.');}$q=db()->prepare('SELECT g.*,u.name author_name,u.role author_role FROM guidances g JOIN users u ON u.id=g.author_id WHERE g.submission_id=? ORDER BY g.meeting_date DESC,g.id DESC');$q->execute([$id]);$guidances=$q->fetchAll();$q=db()->prepare('SELECT d.*,u.name uploader_name FROM documents d JOIN users u ON u.id=d.uploader_id WHERE d.submission_id=? ORDER BY d.created_at DESC');$q->execute([$id]);$documents=$q->fetchAll();page_start('Detail pengajuan');?><div class="detail-heading"><div><a class="back-link" href="index.php?page=submissions">← Kembali ke daftar</a><div class="title-line"><h2><?=e($s['title'])?></h2><?=status_badge($s['status'])?></div><p class="muted">Dibuat <?=e(date('d F Y',strtotime($s['created_at'])))?> · #TA-<?=str_pad((string)$s['id'],4,'0',STR_PAD_LEFT)?></p></div><?php if(is_role('admin')||is_role('dosen')||$s['status']==='diajukan'):?><a class="button secondary" href="index.php?page=submission_form&id=<?=$id?>">✎ Ubah pengajuan</a><?php endif;?></div><div class="detail-grid"><div class="main-column"><article class="panel detail-panel"><div class="panel-heading"><div><p class="eyebrow">INFORMASI PENELITIAN</p><h3>Ringkasan</h3></div><?php if(is_role('admin')):?><form method="post" onsubmit="return confirm('Hapus pengajuan ini beserta dokumen dan catatan bimbingan?')"><?=csrf_field()?><input type="hidden" name="action" value="submission_delete"><input type="hidden" name="id" value="<?=$id?>"><button class="danger-link">Hapus</button></form><?php endif;?></div><p class="description-text"><?=nl2br(e($s['description']?:'Belum ada deskripsi.'))?></p></article><article class="panel detail-panel"><div class="panel-heading"><div><p class="eyebrow">RIWAYAT PERTEMUAN</p><h3>Catatan bimbingan</h3></div></div><form method="post" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="guidance_save"><input type="hidden" name="submission_id" value="<?=$id?>"><label>Tanggal<input type="date" name="meeting_date" value="<?=date('Y-m-d')?>" required></label><label class="grow">Catatan<textarea name="note" rows="2" required placeholder="Topik yang dibahas, arahan, dan tindak lanjut..."></textarea></label><button class="button primary">Tambah catatan</button></form><div class="timeline"><?php foreach($guidances as $g):?><div class="timeline-item"><span class="timeline-dot"></span><div class="timeline-top"><strong><?=e($g['author_name'])?></strong><span><?=e(date('d M Y',strtotime($g['meeting_date'])))?></span></div><p><?=nl2br(e($g['note']))?></p><?php if(is_role('admin')||is_role('dosen')||(int)$g['author_id']===(int)current_user()['id']):?><form method="post" onsubmit="return confirm('Hapus catatan ini?')"><?=csrf_field()?><input type="hidden" name="action" value="guidance_delete"><input type="hidden" name="id" value="<?=$g['id']?>"><button class="danger-link">Hapus catatan</button></form><?php endif;?></div><?php endforeach;?><?php if(!$guidances):?><p class="empty">Belum ada catatan bimbingan.</p><?php endif;?></div></article></div><div class="side-column"><article class="panel info-panel"><p class="eyebrow">DETAIL PENGAJUAN</p><div class="info-row"><span>Mahasiswa</span><strong><?=e($s['student_name'])?></strong><?php if($s['student_number']):?><small><?=e($s['student_number'])?></small><?php endif;?></div><div class="info-row"><span>Dosen pembimbing</span><strong><?=e($s['lecturer_name']??'Belum ditentukan')?></strong></div><div class="info-row"><span>Status saat ini</span><?=status_badge($s['status'])?></div><div class="info-row"><span>Pembaruan terakhir</span><strong><?=e(date('d M Y',strtotime($s['updated_at'])))?></strong></div></article><article class="panel info-panel"><div class="panel-heading"><div><p class="eyebrow">ARSIP</p><h3>Dokumen</h3></div></div><form method="post" enctype="multipart/form-data" class="upload-form"><?=csrf_field()?><input type="hidden" name="action" value="document_upload"><input type="hidden" name="submission_id" value="<?=$id?>"><input type="file" name="document" accept=".pdf,.doc,.docx,.jpg,.jpeg,.png" required><small>PDF, DOC, DOCX, JPG, PNG · maks. 10 MB</small><button class="button secondary">＋ Unggah dokumen</button></form><div class="document-list"><?php foreach($documents as $d):?><div class="document-item"><span class="file-icon">↧</span><div><a href="index.php?page=download&id=<?=$d['id']?>"><?=e($d['original_name'])?></a><small><?=e(number_format($d['file_size']/1024,0))?> KB · <?=e($d['uploader_name'])?></small></div><?php if(is_role('admin')||is_role('dosen')||(int)$d['uploader_id']===(int)current_user()['id']):?><form method="post" onsubmit="return confirm('Hapus dokumen ini?')"><?=csrf_field()?><input type="hidden" name="action" value="document_delete"><input type="hidden" name="id" value="<?=$d['id']?>"><button class="danger-link" aria-label="Hapus dokumen">×</button></form><?php endif;?></div><?php endforeach;?><?php if(!$documents):?><p class="empty">Belum ada dokumen.</p><?php endif;?></div></article></div></div><?php page_end();exit; }
